/// Returns the number of decimal digits equal to 7 in `x`.
///
/// Specification (recursive):
/// - If x < 10: result is 1 iff x == 7, else 0.
/// - If x >= 10: result is (last digit == 7 ? 1 : 0) + count7(x / 10).
///
/// For x in [0, 255], the result is in [0, 3].
fn count7(x: u8) -> u8 {
    // Iterate over decimal digits by repeated division by 10.
    let mut n = x;
    let mut count: u8 = 0;

    loop {
        if n % 10 == 7 {
            count += 1;
        }
        n /= 10;
        if n == 0 {
            break;
        }
    }

    count
}

